:root {
--radius-none: 0;
--radius-sm: 4px;      /* --v_radius_sm — 추천 라벨·칩 */
--radius-md: 6px;      /* --v_radius — 썸네일·채널 칩·검색창 */
--radius-lg: 8px;      /* --v_radius_md — 투고 버튼·팝오버 */
--radius-xl: 12px;     /* --v_radius_xl — 모달·큰 카드 (10px --v_radius_lg 도 있음) */
--radius-full: 9999px; /* 아바타·동그란 채널 아이콘 */
--shadow-none: none;                           /* 영상 카드 — 그림자 없이 평평 */
--shadow-sm: 0 2px 4px rgba(0, 0, 0, 0.08);    /* 떠 있는 버튼·툴팁 */
--shadow-md: 0 0 30px rgba(0, 0, 0, 0.10);     /* 헤더 드롭다운·팝오버 (실측 최빈) */
--shadow-lg: 0 8px 40px rgba(0, 0, 0, 0.10);   /* 큰 패널·모달 */
--shadow-xl: 0 12px 48px rgba(0, 0, 0, 0.16);  /* (추정) 풀스크린 다이얼로그 */
--duration-fast: 200ms;   /* (추정) 아이콘 hover */
--duration-base: 300ms;   /* 실측 — 채널 칩·투고 버튼 background-color .3s */
--duration-slow: 500ms;   /* (추정) 배너 교차 전환 */
--ease-out: cubic-bezier(0.22, 0.61, 0.36, 1);  /* (추정) */
--ease-in-out: ease;                             /* 실측 transition 기본값 */
}
:root {
  /* Primary - brand_pink (bili_dark Pi 팔레트) */
  --color-primary-50:  #26161C;  /* Pi0 */
  --color-primary-100: #2F1A22;  /* Pi1 = brand_pink_thin */
  --color-primary-200: #472030;  /* Pi2 */
  --color-primary-300: #76304B;  /* Pi3 = brand_pink_disabled */
  --color-primary-400: #A73E65;  /* Pi4 */
  --color-primary-500: #D44E7D;  /* Pi5 = brand_pink (다크) */
  --color-primary-600: #DC6D94;  /* Pi6 */
  --color-primary-700: #E38CAA;  /* Pi7 */
  --color-primary-800: #EBABC1;  /* Pi8 */
  --color-primary-900: #F2CAD8;  /* Pi9 */
  --color-primary-legacy: #FB7299;  /* 헤더 「投稿」 버튼 하드코딩 — 테마 무관 (추정) */

  /* Secondary - brand_blue (bili_dark Lb 팔레트) */
  --color-secondary-100: #0B202A;  /* Lb1 = brand_blue_thin */
  --color-secondary-400: #006996;  /* Lb4 */
  --color-secondary-500: #0087BD;  /* Lb5 = brand_blue (다크) */
  --color-secondary-600: #2C9CC8;  /* Lb6 */
  --color-link:          #58B1D4;  /* Lb7 = text_link */

  /* Neutral - Ga 팔레트 (다크, 0 = 가장 어두운 면) */
  --color-neutral-0:    #17181A;  /* Wh0 — bg1 */
  --color-neutral-50:   #101011;  /* Ga0 — bg2 */
  --color-neutral-100:  #0A0B0C;  /* Ga1 — bg3 */
  --color-neutral-200:  #2F3134;  /* Ga2 — line_regular */
  --color-neutral-300:  #46494D;  /* Ga3 — line_bold, text4 */
  --color-neutral-500:  #757A81;  /* Ga5 — text3 */
  --color-neutral-700:  #A2A7AE;  /* Ga7 — text2 */
  --color-neutral-900:  #E7E9EB;  /* Ga10 — text1 */
  --color-neutral-1000: #FFFFFF;

  /* Semantic */
  --color-success-bg: #11271B;  /* Gr1 */
  --color-success-fg: #1FA251;  /* Gr5 */
  --color-warning-bg: #31190F;  /* Or1 */
  --color-warning-fg: #E1540D;  /* Or5 */
  --color-error-bg:   #2E1617;  /* Re1 */
  --color-error-fg:   #D1403E;  /* Re5 */
  --color-info-bg:    #0B202A;  /* Lb1 */
  --color-info-fg:    #0087BD;  /* Lb5 */
  --color-pay:        #DB8700;  /* Ye5 */

  /* Surface (배경 위계) */
  --bg-base:     #17181A;            /* bg1 */
  --bg-subtle:   #101011;            /* bg2 */
  --bg-elevated: #242628;            /* bg1_float — 팝오버·카드 */
  --bg-overlay:  rgba(0, 0, 0, 0.6); /* (추정) */

  /* Text 위계 */
  --text-primary:    #E7E9EB;  /* text1 */
  --text-secondary:  #A2A7AE;  /* text2 */
  --text-tertiary:   #757A81;  /* text3 */
  --text-on-primary: #FFFFFF;
  --text-disabled:   #46494D;  /* text4 */

  /* Border */
  --border-default: #2F3134;  /* line_regular */
  --border-subtle:  #232527;  /* line_light (Ga1_s) */
  --border-strong:  #46494D;  /* line_bold */
  --border-focus:   #0087BD;  /* (추정) */
}

[data-theme="light"] {
  --color-primary-50: #FFF3F6; --color-primary-100: #FFECF1; --color-primary-200: #FFD9E4; --color-primary-300: #FFB3CA; --color-primary-400: #FF8CB0;
  --color-primary-500: #FF6699; --color-primary-600: #E84B85; --color-primary-700: #D03171; --color-primary-800: #AD1C5B; --color-primary-900: #771141;
  --color-secondary-100: #DFF6FD; --color-secondary-400: #40C5F1; --color-secondary-500: #00AEEC; --color-secondary-600: #008AC5; --color-link: #00699D;
  --color-neutral-0: #FFFFFF; --color-neutral-50: #F6F7F8; --color-neutral-100: #F1F2F3; --color-neutral-200: #E3E5E7; --color-neutral-300: #C9CCD0;
  --color-neutral-500: #9499A0; --color-neutral-700: #61666D; --color-neutral-900: #18191C; --color-neutral-1000: #000000;
  --color-success-bg: #E4F8EA; --color-success-fg: #2AC864; --color-warning-bg: #FFEDE2; --color-warning-fg: #FF661A;
  --color-error-bg: #FEECEA; --color-error-fg: #F85A54; --color-info-bg: #DFF6FD; --color-info-fg: #00AEEC; --color-pay: #FFB027;
  --bg-base: #FFFFFF; --bg-subtle: #F6F7F8; --bg-elevated: #FFFFFF; --bg-overlay: rgba(0, 0, 0, 0.5);
  --text-primary: #18191C; --text-secondary: #61666D; --text-tertiary: #9499A0; --text-on-primary: #FFFFFF; --text-disabled: #C9CCD0;
  --border-default: #E3E5E7; --border-subtle: #F1F2F3; --border-strong: #C9CCD0; --border-focus: #00AEEC;
}




.bl-btn { height: 34px; padding: 0 16px; border: 0; border-radius: var(--radius-lg); font: 500 14px/20px 'HarmonyOS Sans SC', 'PingFang SC', sans-serif; display: inline-flex; align-items: center; gap: 6px; cursor: pointer; transition: background-color .3s; }
.bl-btn--primary { background: var(--color-primary-500); color: var(--text-on-primary); }       /* 关注·投稿 */
.bl-btn--primary:hover { background: var(--color-primary-400); }                               /* hover 는 밝아진다 */
.bl-btn--primary:active { background: var(--color-primary-600); }
.bl-btn--secondary { background: var(--color-secondary-500); color: #fff; }                     /* 登录·확인 */
.bl-btn--secondary:hover { background: var(--color-secondary-400); }
.bl-btn--ghost { background: var(--bg-subtle); color: var(--text-secondary); border: 1px solid var(--border-subtle); }
.bl-btn--ghost:hover { background: var(--color-neutral-200); }
.bl-btn--danger { background: var(--color-error-fg); color: #fff; }
.bl-btn:disabled { background: var(--color-primary-300); cursor: not-allowed; }                 /* brand_pink_disabled */
.bl-btn.is-loading { opacity: .7; pointer-events: none; }
.bl-btn.is-loading::before { content: ""; width: 12px; height: 12px; border: 2px solid rgba(255,255,255,.5); border-top-color: #fff; border-radius: 50%; animation: bl-spin .8s linear infinite; }
@keyframes bl-spin { to { transform: rotate(360deg); } }
.bl-search { height: 32px; padding: 0 8px; border: 2px solid transparent; border-radius: var(--radius-md); background: var(--color-neutral-200); color: var(--text-primary); font-size: 14px; }  /* 실측: graph_bg_thick */
.bl-search:focus { outline: none; background: var(--bg-base); border-color: var(--border-focus); }
.bl-search.is-error { border-color: var(--color-error-fg); }
.bl-search:disabled { color: var(--text-disabled); background: var(--bg-subtle); }
.bl-vcard { background: transparent; }
.bl-vcard__cover { position: relative; aspect-ratio: 16 / 10; border-radius: var(--radius-md); overflow: hidden; background: var(--bg-subtle); }
.bl-vcard__stats { position: absolute; left: 0; right: 0; bottom: 0; height: 38px; padding: 16px 8px 6px; background-image: linear-gradient(180deg, rgba(0,0,0,0), rgba(0,0,0,.8)); color: #fff; font-size: 13px; display: flex; align-items: center; justify-content: space-between; }
.bl-vcard__title { margin-top: 8px; font-size: 15px; line-height: 22px; height: 44px; font-weight: 500; color: var(--text-primary); display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; overflow: hidden; }
.bl-vcard__title:hover { color: var(--color-secondary-500); }
.bl-vcard__owner { margin-top: 4px; font-size: 13px; color: var(--text-tertiary); }
.bl-card--accent { background: var(--color-primary-100); border-radius: var(--radius-lg); padding: 16px; }
.bl-card--outlined { border: 1px solid var(--border-default); border-radius: var(--radius-lg); padding: 16px; }
.bl-tag { display: inline-flex; align-items: center; height: 18px; padding: 0 4px; border-radius: var(--radius-sm); font-size: 12px; }
.bl-tag--solid { background: var(--color-primary-500); color: #fff; }                       /* 大会员·独家 */
.bl-tag--subtle { background: var(--color-warning-bg); color: var(--color-warning-fg); }    /* 「1万点赞」 추천 라벨 (실측 Or5/Or1) */
.bl-tag--outline { border: 1px solid var(--color-primary-500); color: var(--color-primary-500); }
.bl-count { min-width: 16px; height: 16px; padding: 0 4px; border-radius: 8px; background: var(--color-error-fg); color: #fff; font-size: 11px; line-height: 16px; text-align: center; }
.bl-header { height: 64px; display: flex; align-items: center; gap: 16px; padding: 0 24px; background: transparent; color: #fff; font-size: 14px; }   /* 배너 위에 투명하게 겹친다 */
.bl-header.is-fixed { background: var(--bg-base); color: var(--text-primary); box-shadow: 0 2px 4px rgba(0,0,0,.08); }
.bl-upload { width: 90px; height: 34px; border-radius: var(--radius-lg); background: var(--color-primary-legacy); color: #fff; font-weight: 500; }   /* 실측 #FB7299 */
.bl-channel { height: 30px; line-height: 30px; padding: 0 12px; border: 1px solid var(--border-subtle); border-radius: var(--radius-md); background: var(--bg-subtle); color: var(--text-secondary); font-size: 14px; transition: background-color .3s, color .3s; }
.bl-channel:hover { background: var(--color-neutral-200); color: var(--text-primary); }
